import React, { PropsWithChildren, ReactNode } from 'react';
import { isElement } from 'react-is';

import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { iterateChartInteractionsSlots } from '../../core/functions/iterate-chart-interactions-slots.js';
import { ChartInteractions } from '../../core/slots/chart-interactions/ChartInteractions.js';
import { ChartToolbar } from '../../core/slots/toolbar/ChartToolbar.js';
import { DownloadData } from '../../core/slots/toolbar/DownloadData.js';
import {
  TimeseriesAnnotationsMarkerProps,
  TimeseriesAnnotationsTrackRendererProps,
} from '../context/TimeseriesChartAnnotationsConfig.context.js';
import {
  Annotations,
  TimeseriesChartAnnotationsProps,
} from '../slots/annotations/Annotations.js';
import { Marker } from '../slots/annotations/Marker.js';
import { Track } from '../slots/annotations/Track.js';
import { Legend, TimeseriesChartLegendProps } from '../slots/Legend.js';
import { Area, TimeseriesChartAreaProps } from '../slots/shapes/Area.js';
import { Band } from '../slots/shapes/Band.js';
import { Bar, TimeseriesChartBarProps } from '../slots/shapes/Bar.js';
import { Line, TimeseriesChartLineProps } from '../slots/shapes/Line.js';
import {
  Threshold,
  TimeseriesChartThresholdProps,
} from '../slots/Threshold.js';
import { TimeseriesChartTooltipProps, Tooltip } from '../slots/Tooltip.js';
import { TimeseriesChartXAxisProps, XAxis } from '../slots/XAxis.js';
import { TimeseriesChartYAxisProps, YAxis } from '../slots/YAxis.js';
import {
  TimeseriesBandSlotProps,
  TimeseriesChartBandProps,
} from '../types/timeseries-band.js';
import { TimeseriesChartSlots } from '../types/timeseries-config.js';
import {
  ChartVariantInternal,
  TimeseriesAreaSlotProps,
  TimeseriesBarSlotProps,
  TimeseriesLineSlotProps,
  TimeseriesPerVariant,
} from '../types/timeseries.js';
import { TimeseriesChartToolbarConfig } from '../types/toolbar.js';

/**
 * Generate chart config based on slots
 * @param children - TimeseriesChart children
 * @returns TimeseriesChartSlots slot config
 */
export const iterateConfigSlots = (
  children: React.ReactNode,
): TimeseriesChartSlots => {
  let slots: TimeseriesChartSlots = {
    toolbar: {},
    legend: {},
    xAxis: {},
    tooltip: {},
    yAxis: [],
    thresholds: [],
    interactions: {},
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case ChartInteractions: {
          const { children, ...previousInteractions } = child.props;

          const interactions = iterateChartInteractionsSlots(children);

          slots = {
            ...slots,
            interactions: {
              ...previousInteractions,
              ...interactions,
            },
          };
          break;
        }
        case ChartToolbar: {
          const { children, ...toolbar } =
            child.props as PropsWithChildren<TimeseriesChartToolbarConfig>;
          const childrenToolbar = iterateChartToolbarSlots(children);

          slots = {
            ...slots,
            toolbar: {
              enabled: true,
              ...toolbar,
              ...childrenToolbar,
            },
          };
          break;
        }
        case Legend: {
          const legend = child.props as TimeseriesChartLegendProps;

          slots = {
            ...slots,
            legend,
          };
          break;
        }
        case XAxis: {
          const xAxis = child.props as TimeseriesChartXAxisProps;
          slots = {
            ...slots,
            xAxis,
          };
          break;
        }
        case YAxis: {
          const yAxis = child.props as TimeseriesChartYAxisProps;

          slots.yAxis.push(yAxis);
          break;
        }
        case Tooltip: {
          const tooltip = child.props as TimeseriesChartTooltipProps;
          slots = {
            ...slots,
            tooltip,
          };
          break;
        }
        case Annotations: {
          const { children, ...annotationsProps } =
            child.props as React.PropsWithChildren<TimeseriesChartAnnotationsProps>;

          const tracks = iterateTrackSlots(children);

          const annotations = {
            ...annotationsProps,
            tracks,
          };

          slots = {
            ...slots,
            annotations,
          };
          break;
        }
        case Threshold: {
          const thresholdProps = child.props as TimeseriesChartThresholdProps;

          slots.thresholds.push(thresholdProps);

          break;
        }
      }
    }
  });

  return slots;
};

/**
 * Generate config based on the Tracks and Markers slots
 * @param children - Annotations children
 * @returns tracks configuration including the markers
 */
const iterateTrackSlots = (children: ReactNode) => {
  const tracks: TimeseriesAnnotationsTrackRendererProps[] = [];

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      if (child.type === Track) {
        const { children, ...trackProps } = child.props;
        const currentTrack: {
          markers: TimeseriesAnnotationsMarkerProps[];
        } = {
          ...trackProps,
          markers: [],
          ...trackProps,
        };

        React.Children.forEach(children, (child) => {
          if (isElement(child)) {
            if (child.type === Marker) {
              const markerProps = { ...child.props, id: uuidv4() };
              currentTrack.markers.push(markerProps);
            }
          }
        });
        tracks.push(currentTrack);
      }
    }
  });

  return tracks;
};

/**
 * Generate chart config based on slots
 * @param children - CharInteraction children
 * @returns ChartInteraction slot config
 */
const iterateChartToolbarSlots = (
  children: React.ReactNode,
): TimeseriesChartToolbarConfig => {
  let toolbar = {};

  React.Children.forEach(children, (childToolbar) => {
    if (isElement(childToolbar) && childToolbar.type === DownloadData) {
      toolbar = {
        ...toolbar,
        downloadData: { enabled: true },
      };
    }
  });

  return toolbar;
};

/**
 * Generate chart config based on slots
 * @param children - chartSeries children
 * @param defaultVariant - The variant defined at root level of TimeseriesChart
 * @returns ChartSeries slot config
 */
export const iterateChartSeriesSlots = (
  children: React.ReactNode,
): TimeseriesPerVariant => {
  const line: TimeseriesLineSlotProps[] = [];
  const bar: TimeseriesBarSlotProps[] = [];
  const area: TimeseriesAreaSlotProps[] = [];
  const band: TimeseriesBandSlotProps[] = [];
  const shapePriority: ChartVariantInternal[] = [];

  React.Children.forEach(children, (childSlot) => {
    if (isElement(childSlot)) {
      switch (childSlot.type) {
        case Line: {
          const { data, ...overrides } =
            childSlot.props as TimeseriesChartLineProps;
          line.push({ ...data, ...overrides });
          if (!shapePriority.includes('line')) {
            shapePriority.push('line');
          }
          break;
        }
        case Bar: {
          const { data, ...overrides } =
            childSlot.props as TimeseriesChartBarProps;
          bar.push({ ...data, ...overrides });
          if (!shapePriority.includes('bar')) {
            shapePriority.push('bar');
          }
          break;
        }
        case Area: {
          const { data, ...overrides } =
            childSlot.props as TimeseriesChartAreaProps;
          area.push({ ...data, ...overrides });
          if (!shapePriority.includes('area')) {
            shapePriority.push('area');
          }
          break;
        }
        case Band: {
          const {
            data,
            strokeOnly = false,
            color,
            gapPolicy,
          } = childSlot.props as TimeseriesChartBandProps;
          band.push({ ...data, strokeOnly, color, gapPolicy });
          if (!shapePriority.includes('band')) {
            shapePriority.push('band');
          }
          break;
        }
      }
    }
  });

  return { band, line, area, bar, shapePriority };
};
